SELECT DISTINCT ON ("bs"."bus_stop_id") "bs"."bus_stop_code" , "bs"."bus_stop_en_name" , "bs"."bus_stop_kana_name" , "bs"."bus_stop_name" , "bs"."bus_stop_type" , "bs"."bus_stop_url" , "bs"."latitude_longitude" , "sp"."signpost_branch_number" , "sp"."signpost_en_name" , "sp"."signpost_kana_name" FROM "line_route_bus_stops" AS "lrbs" INNER JOIN "line_routes" AS "lr" ON "lr"."del_flag" = 0 AND "lr"."line_route_id" = "lrbs"."line_route_id" AND "lr"."rosen_id" IN
#{id}
INNER JOIN "signposts" AS "sp" ON "sp"."del_flag" = 0 AND "sp"."available_flag" = 1 AND "sp"."signpost_id" = "lrbs"."signpost_id" INNER JOIN "bus_stops" AS "bs" ON "bs"."del_flag" = 0 AND "bs"."available_flag" = 1 AND "bs"."indoor_bus_terminal_flag" = 1 AND "bs"."bus_stop_id" = "sp"."bus_stop_id" WHERE "lrbs"."del_flag" = 0 ORDER BY "bs"."bus_stop_id" ASC , "sp"."signpost_id" ASC

SELECT DISTINCT ON ("sp"."signpost_id") "bs"."bus_stop_code" AS "busStopCode" , "lrbs"."signpost_id" AS "signpostId" , "sp"."bus_stop_id" AS "busStopId" , "sp"."bus_stop_type" AS "busStopType" , "sp"."latitude_longitude" AS "latitudeLongitude" , "sp"."platform_code" AS "platformCode" , "sp"."signpost_branch_number" AS "signpostBranchNumber" , "sp"."signpost_code" AS "signpostCode" , "sp"."signpost_desc" AS "signpostDesc" , "sp"."signpost_id" AS "signpostId" , "sp"."signpost_name" AS "signpostName" , "sp"."signpost_kana_name" AS "signpostKanaName" , "sp"."signpost_en_name" AS "signpostEnName" , "sp"."signpost_sub_name" AS "signpostSubName" , "sp"."signpost_url" AS "signpostUrl" , "sp"."wheelchair_accessible_type" AS "wheelchairAccessibleType" , "bs"."indoor_bus_terminal_flag" AS "indoorBusTerminalFlag" FROM "line_route_bus_stops" AS "lrbs" INNER JOIN "line_routes" AS "lr" ON "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 AND "lr"."line_route_id" = "lrbs"."line_route_id" AND "lr"."rosen_id" IN
#{id}
INNER JOIN "signposts" AS "sp" ON "sp"."del_flag" = 0 AND "sp"."available_flag" = 1 AND "sp"."signpost_id" = "lrbs"."signpost_id" INNER JOIN "bus_stops" AS "bs" ON "bs"."del_flag" = 0 AND "bs"."available_flag" = 1 AND "bs"."bus_stop_id" = "sp"."bus_stop_id" WHERE "lrbs"."del_flag" = 0 ORDER BY "sp"."signpost_id" ASC
